"""The .claude/bin/ launchers a project uses to reach the installed plugin.

They embed the absolute plugin path, so they are machine-specific (gitignored)
and rewritten at every session start: a plugin upgrade moves the install path.
"""

from __future__ import annotations

import shlex
from pathlib import Path

from .fsutil import write_if_changed
from .project import Project

# name in .claude/bin -> script under <plugin>/bin
LAUNCHERS = {"tasks": "tasks.py", "board": "board.py", "sandbox": "sandbox.py"}

_TEMPLATE = """#!/bin/sh
# Generated by foreman at every session start. Do not edit.
exec python3 -I {script} "$@"
"""


def launcher_content(plugin_root: Path, script: str) -> str:
    return _TEMPLATE.format(script=shlex.quote(str(plugin_root / "bin" / script)))


def ensure_launchers(project: Project, plugin_root: Path) -> dict[str, str]:
    """Write every launcher. Returns {name: created|updated|unchanged}."""
    results = {}
    for name, script in LAUNCHERS.items():
        results[name] = write_if_changed(
            project.bin_dir / name, launcher_content(plugin_root, script), mode=0o755
        )
    gitignore = project.bin_dir / ".gitignore"
    if not gitignore.exists():
        write_if_changed(gitignore, "# machine-specific launchers, regenerated by foreman\n*\n")
    return results
